        'purito-seoul-timeless-bloom-retinol-spot-cream' => ['بيوريتو سيول - كريم الريتينول الموضعي تايملس بلوم', '<div>يجمع كريم الريتينول الموضعي تايملس بلوم من بيوريتو سيول بين 0.1% من الريتينول النقي والباكوتشيول ومستخلص أوراق الهيدرانجيا من جيجو لاستهداف علامات التقدّم في السن الظاهرة. تساعد تركيبته المركّزة على تنعيم مظهر التجاعيد وتحسين ملمس البشرة ودعم مرونتها، بينما يساعد حمض الهيالورونيك والجلسرين على الحفاظ على ترطيبها. يترك قوامه الغني الخالي من العطور البشرةَ مرطّبة بلمسة نهائية ناعمة ومرنة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>يساعد الريتينول والباكوتشيول على تقليل مظهر التجاعيد.</li><li>يساعد مستخلص أوراق الهيدرانجيا من جيجو على تحسين مظهر مرونة البشرة.</li><li>يساعد على تنعيم الخشونة ومنح البشرة مظهرًا أكثر توحّدًا.</li><li>يساعد حمض الهيالورونيك والجلسرين على الحفاظ على رطوبة البشرة.</li><li>يساعد الألانتوين ومستخلص الشاي الأخضر على تهدئة البشرة وراحتها.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>الريتينول 0.1% والباكوتشيول: يساعدان على تنعيم مظهر التجاعيد وتحسين ملمس البشرة.</li><li>مستخلص أوراق الهيدرانجيا من جيجو وحمض الهيالورونيك: يساعدان على دعم مرونة البشرة والحفاظ على ترطيبها.</li></ul></div></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>ضعي كمية بحجم حبة البازلاء على المناطق المستهدفة كخطوة أخيرة في روتين العناية المسائي.</li><li>ابدئي باستخدامه ليلة بعد ليلة، ثم زيدي الاستخدام تدريجيًا مع تكيّف بشرتك.</li><li>تجنّبي في البداية دمجه مع الأحماض المقشّرة أو المقشّرات الحبيبية لتقليل خطر التهيّج.</li><li>ضعي واقي شمس واسع الطيف خلال النهار.</li></ul></div></div><div class="kbb-bl"></div><div>الأنسب للبشرة الجافة والدهنية والمختلطة التي تعاني من الخطوط الدقيقة والتجاعيد وعدم انتظام الملمس وفقدان الشدّ.</div><div class="kbb-bl"></div><div><b>الحجم: </b>30 مل<br><br></div><div><b>عن العلامة التجارية: </b>تتبنّى بيوريتو سيول نهجًا يضع البشرة أولًا ويؤمن بأن القليل يكفي في العناية الكورية بالبشرة، فتركّز على ما تحتاجه بشرتك فعلًا وتستغني عمّا لا داعي له. تنطلق العلامة من المكوّنات المهدّئة والعناية بحاجز البشرة، لتقدّم تركيبات لطيفة وهادفة تساعد البشرة المجهدة على استعادة مظهر هادئ ومتوازن وصحي.</div>'],
        'celimax-retinal-booster-and-cream-set' => ['سيليماكس - مجموعة بوستر وكريم الريتينال', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>تساعد على تحسين مظهر الخطوط الدقيقة والتجاعيد لبشرة أنعم وأكثر صفاءً.</li><li>يساعد الريتينال وببتيدات Matrixyl على دعم شدّ البشرة وتحسين مظهر تراجع المرونة.</li><li>صُمّمت تقنية A-Shot™ في البوستر لتعزيز إيصال المكوّنات الفعّالة إلى البشرة.</li><li>يجمع الكريم المزدوج بين العناية المستهدفة بالريتينال وتركيبة مرطّبة غنية بالبانثينول للمساعدة على الحفاظ على ترطيب البشرة وراحتها.</li><li>تساعد على تحسين مظهر المسام الواسعة والملمس غير المنتظم لبشرة بمظهر أكثر توازنًا.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد الريتينال (0.1% في البوستر و0.05% في الكريم المزدوج) وببتيدات Matrixyl على استهداف علامات التقدّم في السن الظاهرة.</li><li>يساعد البانثينول (5% في الكريم المزدوج) على تجديد الرطوبة ودعم حاجز البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>في المساء، نظّفي وجهك وضعي التونر إن رغبتِ.</li><li>ضعي كمية صغيرة من بوستر الشدّ Retinal Shot على المناطق المستهدفة.</li><li>أتبعيه بكريم الشدّ المزدوج Vita-A Retinal Shot، مستفيدةً من تركيبته المرطّبة لدعم راحة البشرة.</li><li>إذا كنتِ تستخدمين الريتينال لأول مرة، فابدئي بليلتين إلى ثلاث ليالٍ أسبوعيًا وزيدي الاستخدام تدريجيًا حسب تحمّل بشرتك.</li><li>استخدمي واقي الشمس كل صباح، وأجري اختبار حساسية للمنتجين قبل الاستخدام الأول.</li></ul><div class="kbb-bl"></div><div>الأنسب للبشرة التي تعاني من الخطوط الدقيقة والتجاعيد والمسام الواسعة وعدم انتظام الملمس وفقدان الشدّ. يُنصح المبتدئات بإدخال الريتينال تدريجيًا، وعلى أصحاب البشرة الحساسة توخّي مزيد من الحذر.</div><div class="kbb-bl"></div></div></div><div><b>محتويات المجموعة:</b></div><div><ul><li>بوستر الشدّ The Vita-A Retinal Shot Tightening Booster – 15 مل</li><li>كريم الشدّ المزدوج The Vita-A Retinal Shot Tightening Dual Cream – 50 مل</li></ul></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تركّز سيليماكس على مشكلات البشرة الحقيقية، فتطوّر منتجات عناية قائمة على المكوّنات بتركيبات مستهدفة لاحتياجات البشرة اليومية. تضمّ مجموعتها الكورية خطوط Noni وHeartleaf وDual Barrier الشهيرة للترطيب والتهدئة والعناية بالمسام ودعم حاجز البشرة. وبنهج عملي يضع التركيبة أولًا، تجعل سيليماكس العناية بالبشرة بسيطة ومركّزة وسهلة الدمج في الروتين اليومي.</div>'],
        'numbuzin-no-2-rose-pdrn-collagen-2x-plumping-serum' => ['نومبوزين - سيروم الامتلاء رقم 2 بـPDRN الورد والكولاجين 2X', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد PDRN الورد على دعم حيوية البشرة وتحسين مظهر البشرة المتعبة والباهتة.</li><li>تساعد خمسة عشر نوعًا من الببتيدات على تحسين مظهر الخطوط الدقيقة ودعم بشرة بمظهر أكثر شدًّا ومرونة.</li><li>يساعد ماء الكولاجين على تجديد الرطوبة، تاركًا البشرة ممتلئة ونديّة ومرنة.</li><li>يساعد النياسيناميد (5%) على تفتيح لون البشرة غير الموحّد ومنحها مظهرًا أكثر إشراقًا.</li><li>تمنح التركيبة ذات القوام الهلامي دفعة منعشة من الترطيب وتساعد على تنعيم مظهر البشرة الجافة والخشنة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد PDRN الورد (10%) و15 نوعًا من الببتيدات على تحسين مظهر الخطوط الدقيقة ودعم شدّ البشرة.</li><li>يساعد ماء الكولاجين (54%) والنياسيناميد (5%) على ترطيب البشرة وملئها وإشراقها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، وزّعي كمية مناسبة بالتساوي على الوجه.</li><li>ربّتي برفق على البشرة مع التركيز على المناطق التي تظهر فيها الخطوط الدقيقة أو فقدان الامتلاء.</li><li>أتبعيه بمرطّب للمساعدة على الاحتفاظ بالترطيب.</li><li>استخدميه صباحًا ومساءً ضمن روتين العناية ببشرتك.</li></ul><div class="kbb-bl"></div></div><div>الأنسب لجميع أنواع البشرة، وخاصة البشرة الجافة من الماء أو الباهتة أو الناضجة التي تعاني من الخطوط الدقيقة وعدم توحّد اللون وفقدان الشدّ.</div><div class="kbb-bl"></div><div><b>الحجم: </b>30 مل</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تعتمد نومبوزين على نظام ترقيم بسيط يسهّل اختيار منتجات العناية بحسب مشكلات البشرة وأهدافها. تضمّ مجموعتها الكورية حلولًا مستهدفة للمسام والترطيب والاحمرار والبقع الداكنة والحبوب وعلامات التقدّم في السن. وبتركيبات تركّز على المكوّنات، تجعل نومبوزين العناية الكورية بالبشرة بسيطة ومستهدفة وسهلة التخصيص.</div>'],
        'dr-reju-all-advanced-pdrn-copper-peptide-serum' => ['دكتور ريجو-أول - سيروم PDRN المتقدّم بببتيدات النحاس', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد PDRN على تحسين حالة البشرة ودعم مظهر أنعم وأكثر صحة.</li><li>تساعد ببتيدات النحاس والببتيدات المتعددة على تحسين مظهر الخطوط الدقيقة ودعم بشرة بمظهر أكثر شدًّا.</li><li>يساعد النياسيناميد على إشراق البشرة الباهتة وتحسين مظهر اللون غير الموحّد.</li><li>يساعد حمض الهيالورونيك والجلسرين على تجديد الرطوبة، تاركين البشرة ممتلئة ومرنة.</li><li>يساعد البانثينول والألانتوين على تهدئة البشرة والحفاظ على رطوبتها لراحة تدوم.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد PDRN (1,200 جزء في المليون) وببتيدات النحاس ومركّب الببتيدات المتعددة على دعم حيوية البشرة وشدّها.</li><li>يساعد النياسيناميد والبانثينول وحمض الهيالورونيك على تحسين الإشراقة وتهدئة البشرة والحفاظ على ترطيبها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي كمية مناسبة على الوجه.</li><li>وزّعي السيروم برفق على البشرة وربّتي عليها حتى يُمتصّ.</li><li>أتبعيه بمرطّب للمساعدة على الحفاظ على الترطيب.</li><li>استخدميه صباحًا ومساءً ضمن روتين العناية ببشرتك.</li></ul><div class="kbb-bl"></div></div><div>الأنسب لجميع أنواع البشرة، وخاصة البشرة الباهتة أو الجافة من الماء أو الناضجة التي تعاني من الخطوط الدقيقة وعدم انتظام الملمس وفقدان الشدّ. إذا كانت بشرتك حساسة للزيوت العطرية، فراجعي قائمة المكوّنات قبل الاستخدام.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>أسّسها صيادلة وأطباء، وتتبنّى دكتور ريجو-أول نهجًا علميًا في العناية الكورية الحديثة بالبشرة وتركيبات K-Pharmacy. تركّز مجموعتها على مكوّنات مستهدفة مثل PDRN وLC-Ceramide وHPR للترطيب والعناية بحاجز البشرة والشدّ وتوحيد اللون. وبتركيبات مُوجَّهة سريريًا، تقدّم دكتور ريجو-أول منتجات عناية كورية مستهدفة مصمّمة حول مشكلات بشرة محدّدة والروتين اليومي.</div>'],
        'epii-hpt6-ultra-cream-5' => ['إبي - كريم HPT6 ألترا 5%', '<div>هل تحتاجين إلى كريم يفعل أكثر من الترطيب؟ يجمع كريم HPT6 ألترا 5% من إبي بين مكوّن العلامة المميّز HPT6 (المكوّن من هيدروكسي بروبيل تتراهيدروبيرانترايول الذي يدعم شدّ البشرة) وMatrixyl Synthe’6 (ببتيد يحفّز البشرة على دعم إنتاج الكولاجين) لاستهداف فقدان المرونة الظاهر. وبفضل مركّب الدهون الداعم للحاجز من السيراميدات والكوليسترول والأحماض الدهنية، تساعد هذه التركيبة على تجديد الرطوبة وتقوية حاجز البشرة لبشرة أكثر شدًّا ونعومة ومرونة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد HPT (5%) على تحسين مظهر شدّ البشرة ومرونتها لبشرة بمظهر أنعم.</li><li>يساعد Matrixyl Synthé’6 (2%) على استهداف الخطوط الدقيقة الظاهرة ودعم مظهر أكثر شدًّا ومرونة.</li><li>يساعد البانثينول (5%) على تجديد الرطوبة وتهدئة الجفاف ودعم الحاجز الطبيعي للبشرة.</li><li>يساعد الإكتوين والألانتوين على تحسين حالة البشرة والحفاظ على ترطيبها وراحتها.</li><li>يساعد حمض الهيالورونيك على جذب الرطوبة والاحتفاظ بها، تاركًا البشرة ممتلئة ومرنة من دون لمسة ثقيلة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد HPT (5%) وMatrixyl Synthé’6 (2%) على تحسين مظهر الخطوط الدقيقة ودعم شدّ البشرة.</li><li>يساعد البانثينول (5%) والإكتوين وحمض الهيالورونيك على تهدئة البشرة وترطيبها ودعم حاجزها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف ووضع السيروم، وزّعي كمية مناسبة على الوجه والرقبة.</li><li>دلّكي برفق وربّتي حتى يُمتصّ.</li><li>استخدميه صباحًا ومساءً كخطوة الترطيب في روتين العناية ببشرتك.</li><li>ضعي واقي الشمس كخطوة أخيرة في روتينك الصباحي.</li></ul><div class="kbb-bl"></div></div><div>الأنسب لجميع أنواع البشرة، وخاصة البشرة التي تعاني من الخطوط الدقيقة وتراجع المرونة والجفاف وفقدان الشدّ.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>50 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقًا من فكرة أن البشرة تتغيّر مع كل مرحلة من مراحل الحياة، تبتكر إبي منتجات عناية كورية مصمّمة لتتكيّف مع احتياجات البشرة المتغيّرة. تضمّ مجموعتها الكورية تركيبات مستهدفة بمكوّنات مثل الإكتوين والبانثينول وPHA والنياسيناميد والببتيدات للترطيب والعناية بالحاجز والإشراقة والملمس. وبنهج لطيف وهادف، تجعل إبي العناية الحديثة بالبشرة أسهل في التخصيص لمختلف مشكلات البشرة والروتين اليومي.</div>'],
        'dr-althea-345-relief-serum' => ['الدكتورة ألثيا - سيروم 345 ريليف', '<div>وداعًا لقلق المرآة! يوفّر سيروم 345 ريليف بقوامه الحليبي ترطيبًا خفيفًا ويقوّي حاجز البشرة بفضل تقنية الليبوسومات الثلاثية ومكوّنات مثل حمض الهيالورونيك والسيراميد NP. ويعمل ماء أوراق شجرة الشاي ومستخلص السنتيلا الآسيوية والنياسيناميد على تهدئة الحبوب وتلاشي الشوائب. المنتج لا يسدّ المسام ومُختبر سريريًا، ومناسب للبشرة الحساسة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد النياسيناميد والريسفيراترول وحمض التانيك على تحسين مظهر الشوائب وآثار الحبوب وعدم توحّد لون البشرة.</li><li>يساعد ماء أوراق شجرة الشاي والسنتيلا الآسيوية على تهدئة الاحمرار الظاهر ودعم بشرة بمظهر أكثر هدوءًا.</li><li>يساعد حمض الهيالورونيك وحمض البولي جلوتاميك على تجديد الرطوبة والحفاظ على البشرة ناعمة ومرطّبة.</li><li>يساعد البانثينول والبيتا جلوكان والماديكاسوسيد على تهدئة الجفاف ودعم راحة البشرة.</li><li>يساعد السيراميد NP على تقوية حاجز الرطوبة في البشرة، بينما يُمتصّ القوام الخفيف من دون لمسة لزجة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد النياسيناميد والريسفيراترول وحمض التانيك على تحسين مظهر الشوائب وعدم توحّد لون البشرة.</li><li>يساعد ماء أوراق شجرة الشاي والسنتيلا الآسيوية والبانثينول والسيراميد NP على تهدئة البشرة وترطيبها ودعم حاجزها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، وزّعي 2–3 قطرات بالتساوي على الوجه.</li><li>ربّتي برفق حتى يُمتصّ تمامًا.</li><li>ضعي طبقة إضافية عندما تحتاج بشرتك إلى مزيد من الترطيب والتهدئة.</li><li>أتبعيه بالمرطّب واستخدمي واقي الشمس خلال النهار.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة الحساسة والمختلطة والمعرّضة للحبوب التي تعاني من الاحمرار وآثار الحبوب والجفاف وضعف حاجز البشرة.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تركّز الدكتورة ألثيا على عناية لطيفة وفعّالة في آن، فتبتكر منتجات بتركيبات مدروسة لدعم بشرة بمظهر أكثر صحة. تضمّ مجموعتها الكورية كريمات الحاجز والسيرومات المهدّئة وبلسم التنظيف والأقنعة وواقيات الشمس لمشكلات البشرة اليومية. ومن خلال الجمع بين مكوّنات مختارة بعناية وتركيبات حديثة، تقدّم الدكتورة ألثيا عناية بسيطة تركّز على الترطيب والتهدئة والعناية بحاجز البشرة.</div>'],
        'jumiso-pore-purifying-salicylic-acid-foaming-cleanser' => ['جوميسو - غسول رغوي بحمض الساليسيليك لتنقية المسام', '<div>يقشّر هذا الغسول منخفض الحموضة المُركّب بحمض الساليسيليك والطين الأزرق البشرة وينظّف المسام المسدودة من دون تجريدها من رطوبتها. وبفضل مستخلص فاكهة التفاح ومستخلص جذور الكوبتيس اليابانية، يمنح الغسول فوائد مهدّئة ومفتّحة مع رفع مستوى رطوبة البشرة. تركيبته لا تسدّ المسام ومناسبة لجميع أنواع البشرة بما فيها البشرة المعرّضة للحبوب.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تنظيف المسام بإزالة الدهون الزائدة والشوائب اليومية.</li><li>يقشّر حمض الساليسيليك البشرة بلطف ويساعد على تقليل تراكم الرؤوس السوداء.</li><li>يمتصّ الطين الأزرق الزيوت الزائدة لمظهر أكثر انتعاشًا وأقل لمعانًا.</li><li>يساعد على تحسين مظهر الملمس الخشن لبشرة بمظهر أنعم.</li><li>تركيبة منخفضة الحموضة وخالية من العطور تدعم روتين تنظيف يومي مريح.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد حمض الساليسيليك (0.5%) على تقشير خلايا الجلد الميتة وتنظيف تراكمات المسام.</li><li>يساعد الطين الأزرق على امتصاص الزيوت الزائدة وإزالة الشوائب.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بلّلي وجهك ويديك، ثم اصنعي رغوة غنية من كمية صغيرة.</li><li>دلّكي الوجه برفق مع تجنّب منطقة العينين.</li><li>اشطفي جيدًا بالماء الفاتر، ثم أتبعيه بالتونر والمرطّب.</li><li>استخدميه مرة واحدة يوميًا في البداية، وزيدي عدد المرات حسب تحمّل بشرتك.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة الدهنية والمختلطة والمعرّضة للشوائب التي تعاني من الرؤوس السوداء والدهون الزائدة والمسام الظاهرة.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>120 غ</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تقدّم جوميسو نهجًا عمليًا يركّز على المكوّنات في العناية الكورية بالبشرة، فتبتكر تركيبات مستهدفة لمشكلات البشرة اليومية. تضمّ مجموعتها الكورية منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامينات والديكسبانثينول للترطيب والإشراق والتهدئة والعناية بالمسام والحاجز. وبتركيبات واضحة مبنية على مكوّنات عناية معروفة، تجعل جوميسو الروتين اليومي سهل التخصيص والمواظبة.</div>'],
        'medipeel-gold-age-tox-h8-cream' => ['ميدي بيل - كريم جولد إيج توكس H8', '<div>يحتوي هذا الكريم المضاد لعلامات التقدّم في السن على كبسولات غنية بالمغذّيات وكولاجين نباتي لاستعادة مرونة البشرة ومنحها مظهرًا ممتلئًا وشبابيًا. التركيبة الجلّية غنية بـ19 نوعًا من الأحماض الأمينية ومركّب بروتين الحرير الذهبي لتغذية البشرة وتعزيز إشراقها. كما تحتوي على الأدينوسين لتقليل مظهر التجاعيد. يأتي مع ملعقة صغيرة لمزج الكبسولات والجل معًا قبل وضعه على الوجه.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تحسين مظهر الخطوط الدقيقة وفقدان الشدّ.</li><li>يدعم النياسيناميد بشرة أكثر إشراقًا وتوحّدًا.</li><li>تساعد الببتيدات والكولاجين على منح البشرة مظهرًا أنعم وأكثر امتلاءً.</li><li>تساعد خمسة أنواع من السيراميدات على الحفاظ على الرطوبة ودعم حاجز البشرة.</li><li>يغذّي الجلسرين والبانثينول والسكوالان البشرة ويساعدون على منع فقدان الرطوبة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد النياسيناميد والأدينوسين والببتيدات على تحسين مظهر عدم توحّد اللون والخطوط الدقيقة.</li><li>تساعد خمسة أنواع من السيراميدات والبانثينول والسكوالان على تجديد الرطوبة ودعم حاجز البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>باستخدام الملعقة المرفقة، اغرفي الكبسولات مع الجل المرطّب.</li><li>امزجيهما على ظهر يدك حتى يمتزجا بالتساوي.</li><li>ضعيه على الوجه ودلّكي برفق حتى يُمتصّ.</li><li>استخدميه كخطوة أخيرة في روتين العناية ببشرتك.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة العادية والجافة والناضجة التي تعاني من الخطوط الدقيقة وفقدان الشدّ وعدم توحّد اللون والجفاف.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>50 غ</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تجمع ميدي بيل بين الخبرة التجميلية الاحترافية وأبحاث الأمراض الجلدية لتبتكر منتجات عناية مستهدفة للاستخدام اليومي. تتنوّع مجموعاتها بين علاجات التقشير المتقدّمة والعناية المشدّة الغنية بالببتيدات وتركيبات الترطيب وتجديد البشرة، وكلّ منها مصمّم لمشكلات بشرة محدّدة. ومن خلال الجمع بين الخبرة التجميلية والتركيبات المُختبرة سريريًا، تجعل ميدي بيل العناية المستوحاة من العيادات الاحترافية جزءًا من الروتين اليومي.</div>'],
        'purito-seoul-mighty-bamboo-panthenol-cleanser' => ['بيوريتو سيول - غسول البانثينول مايتي بامبو', null, '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>يزيل الشوائب اليومية دون جفاف مفرط.</li><li>يساعد البانثينول والبيتين على الحفاظ على ترطيب البشرة.</li><li>يساعد على حماية توازن الرطوبة في البشرة.</li><li>يساعد الألانتوين على تهدئة الإحساس بالجفاف وعدم الراحة في البشرة.</li><li>يترك البشرة ناعمة ومنتعشة دون أن يجرّدها من زيوتها الطبيعية.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>مستخلص الخيزران الكوري والبانثينول: يساعدان على دعم حاجز البشرة والحفاظ على رطوبتها.</li><li>الألانتوين والبيتين: يساعدان على تهدئة البشرة وتنعيمها وترطيبها.</li></ul><div class="kbb-bl"></div></div></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>ضعي كمية صغيرة على يدين مبللتين وافركيها حتى تتكوّن رغوة.</li><li>دلّكي بلطف على بشرة الوجه الرطبة مع تجنّب منطقة العينين.</li><li>اشطفي جيداً بالماء الفاتر.</li><li>استخدميه صباحاً ومساءً.</li></ul></div></div><div class="kbb-bl"></div><div>الأنسب لجميع أنواع البشرة، بما فيها البشرة الحساسة والجافة والمفتقرة إلى الترطيب التي تعاني من الشدّ بعد التنظيف.</div><div class="kbb-bl"></div><div><b>الحجم: </b>150 مل</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى بيوريتو سيول نهجاً يضع البشرة أولاً ويؤمن بأن القليل يكفي في العناية الكورية بالبشرة، فتركّز على ما تحتاجه بشرتك فعلاً وتستبعد ما لا داعي له. وانطلاقاً من المكوّنات المهدّئة والعناية بحاجز البشرة، تبتكر العلامة تركيبات لطيفة وهادفة تساعد البشرة المجهدة على استعادة مظهرها الهادئ والمتوازن والصحي.</div>'],
        'abib-pdrn-volume-fill-it-booster-cr-me-2-5-tube' => ['أبيب - كريم PDRN فوليوم فيل-إت بوستر 2.5 - أنبوب', null, '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>يساعد PDRN على دعم بشرة أنعم وأكثر صحة في المظهر وتحسين مظهر الخطوط الرفيعة.</li><li>يساعد الفوليوفيلين على منح مظهر أكثر امتلاءً في المناطق التي تبدو فيها البشرة أقل امتلاءً.</li><li>يساعد الريتينال والببتيدات على تنعيم ملمس البشرة وتلطيف مظهر التجاعيد.</li><li>يساعد النياسيناميد على إشراق البشرة الباهتة وتحسين مظهر تفاوت لونها.</li><li>يساعد البانثينول والسكوالان والسيراميد NP على الحفاظ على الترطيب ودعم حاجز البشرة.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>PDRN بتركيز 15,000 جزء في المليون والفوليوفيلين بتركيز 10,000 جزء في المليون: يساعدان على تحسين مظهر امتلاء البشرة وتماسكها ومرونتها.</li><li>الريتينال ومركّب الببتيدات: يساعدان على تنعيم مظهر الخطوط الرفيعة وتحسين ملمس البشرة.</li></ul></div></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>بعد وضع السيروم، ضعي كمية مناسبة على المناطق المستهدفة مثل الجبهة أو خطوط الابتسامة أو الرقبة.</li><li>وزّعي الكريم بلطف وربّتي عليه حتى يمتصّ.</li><li>أتبعيه بمرطّب عند الحاجة.</li><li>بما أن التركيبة تحتوي على الريتينال، أدخليها إلى روتينك تدريجياً واستخدمي واقي الشمس خلال النها<b>ر.</b></li></ul></div></div><div class="kbb-bl"></div><div><div>الأنسب للبشرة العادية والجافة والناضجة التي تعاني من الخطوط الرفيعة وفقدان التماسك وعدم انتظام الملمس والمناطق التي تبدو أقل امتلاءً.</div><div class="kbb-bl"></div></div><div><b>الحجم: </b>30 مل </div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من فكرة إعادة البشرة إلى حالتها الطبيعية، تبتكر أبيب منتجات عناية بسيطة قائمة على النقاء والبساطة والتركيب المدروس. تضم مجموعتها الكورية منتجات بعشبة القلب ووردة أريحا وPDRN وتركيبات مرطّبة للتهدئة والترطيب والتماسك والعناية بحاجز البشرة. وبنهج قائم على الأبحاث وقوامات راقية، تقدّم أبيب عناية لطيفة تركّز على دعم بشرة صحية ومتوازنة المظهر.</div>'],
        'skin1004-lab-in-nature-madagascar-centella-matrixyl-10-boosting-shot-ampoule' => ['سكين 1004 - أمبول لاب إن نيتشر مدغشقر سنتيلا ماتريكسيل 10 بوستينغ شوت', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li><span>يساعد على تقليل مظهر الخطوط الرفيعة والتجاعيد لبشرة تبدو أنعم وأكثر تماسكاً.</span></li><li><span>يساعد Matrixyl 3000® وVolufiline™ على منح البشرة مظهراً أكثر امتلاءً وتحسين مظهر مرونتها.</span></li><li><span>يساعد حمض الهيالورونيك على تجديد الرطوبة والحفاظ على بشرة مرطّبة ونضرة.</span></li><li><span>تساعد السنتيلا الآسيوية من مدغشقر والبانثينول على تهدئة البشرة ودعم حاجز الرطوبة الطبيعي فيها.</span></li><li><span>تساعد الإبر الدقيقة (Spicules) على تعزيز إيصال المكوّنات، بينما تترك التركيبة المرطّبة البشرة ناعمة دون لمسة ثقيلة.</span></li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>يساعد Matrixyl 3000® (10%) وVolufiline™ (5%) على تحسين مظهر الخطوط الرفيعة ومنح البشرة مظهراً أكثر امتلاءً.</li><li>تساعد السنتيلا الآسيوية من مدغشقر وحمض الهيالورونيك والبانثينول على تهدئة البشرة وترطيبها ودعم حاجزها.</li></ul></div></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي كمية صغيرة على الوجه ووزّعيها بلطف.</li><li>ابدئي باستخدامه 2–3 مرات أسبوعياً أو كل مساءين لتمنحي بشرتك فرصة للتأقلم.</li><li>أتبعيه بمرطّب بعد امتصاص الأمبول، وزيدي عدد مرات الاستخدام تدريجياً إذا تحمّلته بشرتك.</li><li>تجنّبي منطقتي العينين والشفاه، ولا تضعيه على البشرة المتهيّجة أو المتضرّرة.</li><li>أجري اختبار حساسية قبل الاستخدام الأول. قد تشعرين بوخز خفيف بسبب الإبر الدقيقة؛ توقّفي عن الاستخدام إذا استمرّ التهيّج.</li></ul></div><div class="kbb-bl"></div><div>الأنسب للبشرة الجافة والمفتقرة إلى الترطيب والناضجة والعادية التي تعاني من الخطوط الرفيعة وفقدان المرونة والبهتان. يُنصح أصحاب البشرة الحساسة بإدخال هذه التركيبة القائمة على الإبر الدقيقة بحذر.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من نقاء السنتيلا الآسيوية من مدغشقر، تبتكر سكين 1004 منتجات عناية لطيفة تركّز على تهدئة البشرة واستعادة حيويتها. تضم مجموعتها الكورية تركيبات للترطيب والإشراق والعناية بالحاجز والتهدئة، مصنوعة من مكوّنات مختارة بعناية. وتجمع سكين 1004 بين التركيبات البسيطة والمكوّنات المستوحاة من الطبيعة لدعم بشرة مرتاحة ومتوازنة وصحية المظهر.</div>'],
        'numbuzin-no-2-rose-pdrn-collagen-plumping-sheet-mask-5pcs-set' => ['نومبوزين - مجموعة أقنعة ورقية رقم 2 روز PDRN كولاجين للامتلاء - 5 قطع', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد PDRN الورد على العناية بالبشرة وتحسين مظهر البشرة المتعبة والباهتة.</li><li>يساعد ماء الكولاجين والكولاجين على ترطيب البشرة ومنحها مظهراً أكثر امتلاءً ونضارة.</li><li>تساعد تسعة أنواع من الببتيدات على دعم مرونة البشرة وتحسين مظهر الخطوط الرفيعة.</li><li>يساعد النياسيناميد على توحيد مظهر لون البشرة غير المتجانس لإطلالة أكثر إشراقاً.</li><li>يساعد حمض الهيالورونيك والجلسرين على تجديد الرطوبة، تاركين البشرة ناعمة وملساء ومنتعشة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد PDRN الورد وتسعة أنواع من الببتيدات على دعم العناية بالبشرة وتحسين مظهر الخطوط الرفيعة.</li><li>يساعد ماء الكولاجين بنسبة 65% والنياسيناميد وحمض الهيالورونيك على ترطيب البشرة وإبراز امتلائها وإشراقها.</li></ul></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، افردي القناع الورقي وضعيه بالتساوي على الوجه.</li><li>اتركيه لمدة 15–20 دقيقة.</li><li>انزعي القناع وربّتي بلطف على ما تبقّى من الإيسنس حتى يمتصّ في البشرة.</li><li>أتبعيه بمرطّب عند الحاجة.</li></ul></div><div class="kbb-bl"></div><div>الأنسب للبشرة الجافة والمفتقرة إلى الترطيب والباهتة والناضجة التي تعاني من الخطوط الرفيعة وفقدان المرونة ونقص الإشراق.</div><div class="kbb-bl"></div><div><b>الحجم: </b>33 مل × 5 أقنعة</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>بالاعتماد على نظام ترقيم بسيط، تسهّل نومبوزين اختيار منتجات العناية بالبشرة بحسب مشكلات البشرة وأهدافها المحددة. تضم مجموعتها الكورية حلولاً مستهدفة للمسام والترطيب والاحمرار والبقع الداكنة والحبوب وعلامات التقدّم في السن. وبتركيبات تركّز على المكوّنات، تجعل نومبوزين العناية الكورية بالبشرة بسيطة ومستهدفة وسهلة التخصيص.</div>'],
        'skin1004-lab-in-nature-madagascar-centella-retinol-0-2-boosting-shot-ampoule' => ['سكين 1004 - أمبول لاب إن نيتشر مدغشقر سنتيلا ريتينول 0.2 بوستينغ شوت', '<div>وداعاً للتجاعيد وترهّل البشرة! مع الاستخدام المنتظم لأمبول سكين 1004 لاب إن نيتشر مدغشقر سنتيلا ريتينول 0.2 بوستينغ شوت، تصبح استعادة شبابك حقيقة. وبفضل البانثينول والسنتيلا الآسيوية من مدغشقر في مكوّناته، يُقضى على التهيّج والجفاف أيضاً. أما الإبر الدقيقة في التركيبة فتوصل المكوّنات الفعّالة إلى عمق أكبر تحت طبقة الأدمة في البشرة للحصول على أفضل فوائد العناية.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد الريتينول والريتينال على تحسين مظهر الخطوط الرفيعة والتجاعيد لبشرة تبدو أنعم.</li><li>يساعد على تحسين مظهر الملمس الخشن ويدعم بشرة تبدو أكثر تماسكاً ومرونة.</li><li>صُمّمت الإبر الدقيقة لتعزيز إيصال المكوّنات ودعم فعالية أكبر لمنتجات العناية بالبشرة.</li><li>تساعد السنتيلا الآسيوية من مدغشقر والبانثينول على تهدئة البشرة ودعم حاجز الرطوبة الطبيعي فيها.</li><li>يساعد السكوالان وحمض الهيالورونيك على تجديد الرطوبة، تاركين البشرة ناعمة ونضرة ومرطّبة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد الريتينول (0.2%) والريتينال على استهداف علامات التقدّم في السن الظاهرة وتحسين مظهر الملمس غير المنتظم.</li><li>تساعد السنتيلا الآسيوية من مدغشقر والبانثينول والسكوالان على تهدئة البشرة وترطيبها ودعم حاجزها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف، ضعي كمية صغيرة على الوجه مع تجنّب منطقتي العينين والشفاه.</li><li>خلال الأسبوع الأول والثاني، استخدميه 2–3 مرات أسبوعياً أو كل مساءين لمساعدة بشرتك على التأقلم.</li><li>أتبعيه بمرطّب للحفاظ على الترطيب.</li><li>زيدي عدد مرات الاستخدام تدريجياً فقط إذا تحمّلته بشرتك جيداً.</li><li>ضعي واقي الشمس كل صباح وتجنّبي استخدامه على البشرة المتهيّجة أو المتضرّرة. أجري اختبار حساسية قبل الاستخدام الأول.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة العادية والجافة التي تعاني من الخطوط الرفيعة والملمس الخشن وفقدان التماسك. بما أن التركيبة تحتوي على الريتينول والريتينال والإبر الدقيقة، يُنصح أصحاب البشرة الحساسة بإدخالها بحذر.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من نقاء السنتيلا الآسيوية من مدغشقر، تبتكر سكين 1004 منتجات عناية لطيفة تركّز على تهدئة البشرة واستعادة حيويتها. تضم مجموعتها الكورية تركيبات للترطيب والإشراق والعناية بالحاجز والتهدئة، مصنوعة من مكوّنات مختارة بعناية. وتجمع سكين 1004 بين التركيبات البسيطة والمكوّنات المستوحاة من الطبيعة لدعم بشرة مرتاحة ومتوازنة وصحية المظهر.</div>'],
        'epii-hpt6-ultra-cream-10' => ['إبي - كريم HPT6 ألترا 10%', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد HPT (10%) على تحسين مظهر الخطوط الرفيعة ويدعم بشرة تبدو أكثر تماسكاً ومرونة.</li><li>يساعد Matrixyl Synthé’6 (2%) على استهداف علامات التقدّم في السن الظاهرة ويمنح البشرة مظهراً أنعم.</li><li>تساعد السيراميدات والكوليسترول والأحماض الدهنية على تجديد الدهون الأساسية ودعم حاجز الرطوبة في البشرة.</li><li>يساعد البانثينول والإكتوين على تهدئة الجفاف والحفاظ على ترطيب البشرة وراحتها.</li><li>يساعد السكوالان والجلسرين على حبس الرطوبة، تاركين البشرة ناعمة ونضرة ومغذّاة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية:</b></div><div><ul><li>يساعد HPT (10%) وMatrixyl Synthé’6 (2%) على تحسين مظهر الخطوط الرفيعة ودعم تماسك البشرة.</li><li>تساعد السيراميدات والكوليسترول والأحماض الدهنية والبانثينول على تقوية حاجز البشرة والحفاظ على ترطيبها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف ووضع السيروم، وزّعي كمية مناسبة على الوجه والرقبة.</li><li>ربّتي بلطف حتى يمتصّ.</li><li>استخدميه صباحاً ومساءً كخطوة الترطيب في روتين العناية بالبشرة.</li><li>ضعي واقي الشمس كخطوة أخيرة في روتينك الصباحي.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة الجافة والناضجة والمفتقرة إلى الترطيب التي تعاني من الخطوط الرفيعة وتراجع المرونة وضعف حاجز الرطوبة.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>50 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من فكرة أن البشرة تتغيّر مع كل مرحلة من مراحل الحياة، تبتكر إبي منتجات عناية كورية مصمّمة لتتكيّف مع احتياجات البشرة المتغيّرة. تضم مجموعتها الكورية تركيبات مستهدفة بمكوّنات مثل الإكتوين والبانثينول وPHA والنياسيناميد والببتيدات للترطيب والعناية بالحاجز والإشراق وتحسين الملمس. وبنهج لطيف وهادف، تجعل إبي العناية العصرية بالبشرة أسهل تخصيصاً لمختلف مشكلات البشرة والروتين اليومي.</div>'],
        'dr-althea-345-relief-lash-boost-set' => ['الدكتورة ألثيا - مجموعة 345 ريليف الكاملة', '<p>تعرّفي على الثلاثي الجديد لراحة بشرتك! تجمع مجموعة الدكتورة ألثيا 345 ريليف بين بخاخ 345 ريليف وسيروم ريليف المهدّئ وكريم الدكتورة ألثيا 345 ريليف المريح لتمنح البشرة المجهدة العناية التي تستحقها. ترطيب مهدّئ، وبشرة تبدو أكثر سعادة، وذلك التوهّج الناعم والصحي الذي نحبه جميعاً. <span>م</span><span>ثالية للبشرة الحساسة والمعرّضة للحبوب، تساعد هذه المجموعة على الحفاظ على الرطوبة مع دعم حاجز بشرة يبدو أكثر صحة.</span></p>', '<div><b>الفوائد الرئيسية:</b><br><ul><li>روتين 345 أكثر تكاملاً: اجمعي بين البخاخ والسيروم والمرطّب لإنعاش البشرة وتجديد ترطيبها ثم إنهاء الروتين برطوبة مريحة.</li><li>عناية بآثار ما بعد الحبوب: يساعد النياسيناميد والمكوّنات المهدّئة على تحسين مظهر تفاوت لون البشرة والاحمرار المتبقّي.</li><li>ترطيب دون روتين ثقيل: يساعد حمض الهيالورونيك والبانثينول والمكوّنات المرطّبة على تخفيف الإحساس بالجفاف وإبقاء البشرة مرتاحة.</li><li>دعم لحاجز البشرة: تحتوي تركيبات 345 ريليف على مكوّنات مثل البانثينول والسيراميد NP للمساعدة على الحفاظ على الرطوبة ودعم راحة البشرة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>طريقة الاستخدام:</b></div><div><ul><li><b>بخاخ الكريم الدكتورة ألثيا 345 ريليف:</b> بخاخ ثنائي الطبقة يجمع بين الكريم والإيسنس، ينعش البشرة المفتقرة إلى الترطيب ويمنحها تغذية خفيفة، حتى خلال النهار.</li><li><b>كريم الدكتورة ألثيا 345 ريليف:</b> كريم جل مرطّب مصمّم لتهدئة البشرة التي تشعر بالإجهاد وترطيبها ودعم حاجزها.</li><li><b>سيروم الدكتورة ألثيا 345 ريليف:</b> سيروم خفيف بقوام حليبي يحتوي على النياسيناميد والبانثينول وأشكال متعددة من حمض الهيالورونيك ومكوّنات مهدّئة للبشرة المفتقرة إلى الترطيب والبشرة بعد الحبوب.</li></ul></div><div class="kbb-bl"></div><div>الأنسب لمن يرغبن في العناية بالبشرة المفتقرة إلى الترطيب أو التي تشعر بالحساسية أو البشرة بعد الحبوب. </div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>بتركيزها على عناية لطيفة وفعّالة في آن واحد، تبتكر الدكتورة ألثيا منتجات مدروسة التركيب مصمّمة لدعم بشرة تبدو أكثر صحة. تضم مجموعتها الكورية كريمات للحاجز وسيرومات مهدّئة وبلسم تنظيف وأقنعة وواقيات شمس لمشكلات البشرة اليومية. وبالجمع بين مكوّنات مختارة بعناية وتركيبات عصرية، تقدّم الدكتورة ألثيا عناية بسيطة تركّز على الترطيب والتهدئة والعناية بحاجز البشرة.</div>'],
        'jumiso-pore-clearing-cleansing-oil' => ['جوميسو - زيت التنظيف المنقّي للمسام', '<div>بتركيبة غنية بالزيوت النباتية المستخلصة من بذور الجوجوبا وعبّاد الشمس والمكاديميا، يزيل زيت التنظيف هذا الأوساخ والدهون الزائدة والشوائب من المسام بسهولة مع إبعاد التهيّج ونوبات تفاقم البشرة. تُشطف التركيبة الخفيفة والمرطّبة بعمق بسهولة لتكشف عن بشرة ناعمة وملساء بلمسة غير دهنية. المنتج مختبر من قبل أطباء الجلد ومناسب للبشرة الحساسة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يزيل المكياج وواقي الشمس المقاوم للماء والشوائب اليومية.</li><li>يساعد على إذابة الدهون الزائدة والتراكمات حول المسام.</li><li>يساعد زيتا الجوجوبا وبذور عبّاد الشمس على التنظيف مع الحفاظ على رطوبة البشرة.</li><li>يساعد زيت بذور المكاديميا على تنعيم البشرة التي تشعر بالجفاف وتغذيتها.</li><li>تركيبة خفيفة تتحوّل إلى مستحلب عند ملامسة الماء وتُشطف بنظافة دون ترك بقايا ثقيلة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد زيتا الجوجوبا وبذور عبّاد الشمس على إذابة المكياج والدهون الزائدة والشوائب مع الحفاظ على الرطوبة.</li><li>يساعد زيت بذور المكاديميا والسكوالان على تغذية البشرة وتركها ناعمة ومرتاحة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>ضعي 1–2 ضخة على يدين جافتين ودلّكي بلطف على وجه جاف لمدة 1–2 دقيقة.</li><li>أضيفي قليلاً من الماء ليتحوّل الزيت إلى مستحلب بقوام حليبي.</li><li>اشطفي جيداً بالماء الفاتر.</li><li>أتبعيه بغسول مائي الأساس لتنظيف مزدوج كامل.</li></ul><div class="kbb-bl"></div></div><div>الأنسب لجميع أنواع البشرة، بما فيها الجافة والمختلطة والدهنية، الباحثة عن إزالة فعّالة للمكياج وتنظيف للمسام.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>200 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تقدّم جوميسو نهجاً عملياً يركّز على المكوّنات في العناية الكورية بالبشرة، مبتكرةً تركيبات مستهدفة لمشكلات البشرة اليومية. تضم مجموعتها الكورية منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامينات والبانثينول (D-Panthenol) للترطيب والإشراق والتهدئة والعناية بالمسام والحاجز. وبتركيبات مباشرة مبنية على مكوّنات معروفة في العناية بالبشرة، تجعل جوميسو الروتين اليومي سهل التخصيص والمواظبة عليه.</div>'],
        'purito-seoul-oat-in-gentle-exfoliating-face-cleanser' => ['بيوريتو سيول - غسول الوجه المقشّر اللطيف بالشوفان أوت-إن', null, '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>تساعد جزيئات الشوفان على إزالة خلايا الجلد الميتة وتنعيم ملمس البشرة.</li><li>يساعد على إزالة الشوائب اليومية وتنظيف تراكمات المسام.</li><li>يساعد ماء بذور الشوفان والجلسرين وحمض الهيالورونيك على الحفاظ على ترطيب البشرة.</li><li>يساعد البانثينول والسكوالان على إبقاء البشرة ناعمة ومريحة.</li><li>يعمل كغسول للوجه وكقناع طيني في آنٍ واحد.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>ماء بذور الشوفان وجزيئات الشوفان: تساعد على تهدئة البشرة وترطيبها وتقشيرها بلطف.</li><li>البانثينول والسكوالان: يساعدان على الحفاظ على الترطيب ودعم حاجز البشرة.</li></ul><div class="kbb-bl"></div></div></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>للتنظيف اليومي، ضعي كمية مناسبة على البشرة المبللة ودلّكيها بلطف بحركات دائرية.</li><li>اشطفي جيداً بالماء الفاتر.</li><li>لاستخدامه كقناع، ضعي طبقة أكثر سماكة على الوجه واتركيها لمدة 10 دقائق تقريباً، ثم أضيفي الماء ودلّكي بلطف واشطفي.</li><li>تجنّبي منطقة العينين، واضبطي عدد مرات التقشير بحسب تحمّل بشرتك<b>.</b></li></ul></div></div><div class="kbb-bl"></div><div>مناسب لجميع أنواع البشرة، بما فيها البشرة الحساسة، وخاصةً لمن تعاني من خشونة الملمس والجفاف وانسداد المسام.</div><div class="kbb-bl"></div><div><b>الحجم: </b>150 مل</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى بيوريتو سيول نهجاً يضع البشرة أولاً ويؤمن بأن القليل يكفي في العناية الكورية بالبشرة، فتركّز على ما تحتاجه بشرتك حقاً وتستغني عمّا لا داعي له. وبالاعتماد على المكوّنات المهدّئة والعناية بحاجز البشرة، تبتكر العلامة تركيبات لطيفة وهادفة في الوقت نفسه تساعد البشرة المجهدة على استعادة حالة هادئة ومتوازنة ومظهر صحي.</div>'],
        'mixsoon-bean-collagen-hydrogel-mask-set' => ['ميكسون - مجموعة أقنعة الهيدروجيل بالكولاجين والفول', null, '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>يساعد الكولاجين المتحلّل ومستخلص فول الصويا المخمّر على تحسين مظهر مرونة البشرة وامتلائها.</li><li>يساعد الشعير المخمّر والمكوّنات المرطّبة على تجديد الترطيب، فتبدو البشرة ناعمة ومرنة.</li><li>يساعد النياسيناميد على إشراق البشرة الباهتة وتحسين مظهر تفاوت لون البشرة.</li><li>يساعد الرمّان المخمّر على تقشير خلايا الجلد الميتة بلطف وتنعيم ملمس البشرة الخشن.</li><li>يلتصق الهيدروجيل الشفاف بإحكام على الوجه، ليمنح ترطيباً ممتداً بينما يصبح القناع شفافاً تدريجياً.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>الكولاجين المتحلّل ومستخلص فول الصويا المخمّر: يساعدان على دعم مرونة البشرة ومنحها مظهراً أكثر امتلاءً.</li><li>النياسيناميد ومستخلص الرمّان المخمّر: يساعدان على إشراق البشرة الباهتة وتحسين مظهر الملمس غير المتجانس.</li></ul></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، افصلي الجزأين العلوي والسفلي من القناع عن الأغشية الواقية.</li><li>ضعي الجزء السفلي حول الفم والجزء العلوي حول العينين.</li><li>اتركيه لمدة 1–3 ساعات، أو حتى يصبح الهيدروجيل شفافاً.</li><li>انزعي القناع وربّتي بلطف على ما تبقّى من الإيسنس حتى يمتصّه الجلد. </li></ul><div class="kbb-bl"></div></div><div>مناسب لجميع أنواع البشرة، بما فيها البشرة الحساسة، التي تعاني من الجفاف وفقدان النضارة وخشونة الملمس وفقدان المرونة.</div><div class="kbb-bl"></div><div><b>الحجم: </b>35 غ × 5 أقنعة</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تجسّد ميكسون روح البساطة في العناية الكورية بالبشرة، مع التركيز على مكوّنات نقية مختارة بعناية وتركيبات مبسّطة تجعل البشرة محور الاهتمام. تشتهر العلامة بإيسنساتها المميزة بالسنتيلا والفول والغالاكتوميسيس، وتبتكر منتجات عناية خفيفة ومهدّئة مصمّمة لترطيب البشرة وتقوية حاجزها وإبراز إشراقتها الصحية الطبيعية.</div>'],
        'tirtir-mask-fit-make-up-fixer' => ['تيرتير - مثبّت المكياج ماسك فيت', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تثبيت المكياج لفترة أطول ومقاومة التلطّخ الناتج عن العرق والماء والرطوبة.</li><li>توفّر تقنية الرذاذ الناعم تغطية متساوية دون أن يبدو المكياج متكتّلاً أو غير متجانس.</li><li>تركيبة خفيفة تساعد على التحكم في اللمعان الزائد مع إحساس مريح وغير لزج على البشرة.</li><li>يساعد مستخلص السنتيلا الآسيوية على تهدئة البشرة ويدعم تجربة مريحة أثناء وضع المكياج.</li><li>يمكن استخدامه بعد المكياج أو على أدوات المكياج للمساعدة على تحسين توزيع كريم الأساس وثباته.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>مستخلص السنتيلا الآسيوية يساعد على تهدئة البشرة ودعم راحتها.</li><li>يساعد PVP والمكوّنات المكوّنة للغشاء على تكوين طبقة مثبّتة تُبقي المكياج في مكانه.</li></ul></div></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام</b><br><ul><li>رجّي العبوة جيداً قبل الاستخدام.</li><li>أغمضي عينيكِ ورشّي بالتساوي على المكياج النهائي من مسافة 20–30 سم.</li><li>اتركي الرذاذ يجفّ تماماً قبل لمس وجهك.</li><li>لثبات إضافي للمكياج، رشّي كمية صغيرة على إسفنجة أو فرشاة المكياج قبل الاستخدام.</li></ul></div><div class="kbb-bl"></div><div>مناسب لجميع أنواع البشرة، وخاصةً لمن ترغب في مكياج يدوم لفترة أطول بلمسة نهائية خفيفة وغير لزجة.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>80 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تضع تيرتير الجمال الكوري تحت الأضواء بمزيجها المميز من التركيبات عالية الأداء وسهولة الاستخدام واللمسات النهائية المشرقة ذات المظهر الطبيعي. من كوشن ماسك فيت ريد الشهير إلى منتجات المكياج والعناية بالبشرة اللطيفة على البشرة، تبتكر تيرتير أساسيات متعددة الاستخدامات مصمّمة لإبراز جمال بشرتك الطبيعي مع الحفاظ عليها مريحة ونضرة ومشرقة.</div>'],
        'medipeel-peptide-tox-bor-cream' => ['ميدي بيل - كريم الببتيد-توكس بور-كريم', null, '<p class="p1"><b>الفوائد:</b></p><p class="kbb-bl"></p><ul><li>كريم مرطّب غني بالفولوفيلين (Volufiline) و5 أنواع من الببتيدات والأدينوزين لتعزيز مرونة البشرة وتحسين مظهر الخطوط الدقيقة مع تغذية البشرة.</li><li>يجدّد الكولاجين والإيلاستين وحمض الهيالورونيك المهمة لبشرة تبدو صحية.</li><li><span>غني بمستخلص مزرعة خلايا نبات الإديلويس لمنح البشرة عناصر مغذية غنية.</span></li><li><span>يحتوي على 7 مكوّنات مخمّرة تتغلغل في الطبقات العميقة من البشرة مع تقوية حاجز البشرة لزيادة ترطيبها.</span></li></ul><div></div><p class="p1"><b>طريقة الاستخدام:</b></p><p class="kbb-bl"></p><ul><li>خذي كمية معتدلة ووزّعيها بلطف من وسط الوجه نحو أطرافه في الخطوة الأخيرة من روتين العناية بالبشرة.</li></ul>'],
        'numbuzin-no-2-rose-pdrn-collagen-plumping-serum' => ['نومبوزين - سيروم الامتلاء بالكولاجين وPDRN الورد رقم 2', '<div>احصلي على البشرة المشدودة والمرنة التي طالما حلمتِ بها مع هذا السيروم المعزّز للامتلاء والغني بمكوّنات مقاومة لعلامات التقدّم في السن مثل ماء الكولاجين. تركيبة السيروم غنية بـ PDRN الورد والنياسيناميد وستة أنواع من الببتيدات التي تعزّز إنتاج الكولاجين وتحسّن مرونة البشرة. تستهدف التركيبة الوردية الجميلة الخطوط الدقيقة والتجاعيد وتجاعيد زوايا العينين لاستعادة مظهر ممتلئ وشبابي. مناسب للبشرة الحساسة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد PDRN الورد على العناية بالبشرة وتحسين مظهر البشرة الباهتة والمتعبة.</li><li>تساعد ستة أنواع من الببتيدات على تحسين مظهر الخطوط الدقيقة ودعم بشرة تبدو أكثر شدّاً.</li><li>يساعد ماء الكولاجين على تجديد الترطيب، فتبدو البشرة ممتلئة ونديّة ومرنة.</li><li>يساعد النياسيناميد (5%) على توحيد لون البشرة غير المتجانس ومنحها إشراقة أكبر.</li><li>يمنح القوام الهلامي الخفيف ترطيباً يدوم ويساعد على تنعيم مظهر البشرة الجافة والخشنة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد PDRN الورد (5%) وستة أنواع من الببتيدات على تحسين مظهر الخطوط الدقيقة ودعم شدّ البشرة.</li><li>يساعد ماء الكولاجين (63%) والنياسيناميد (5%) على ترطيب البشرة وامتلائها وإشراقها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي 2–3 ضغطات بالتساوي على الوجه.</li><li>ربّتي بلطف حتى يمتص الجلد السيروم.</li><li>للمناطق التي تحتاج إلى ترطيب إضافي ومظهر أكثر امتلاءً، ضعي طبقة إضافية.</li><li>اتبعيه بالمرطّب واستخدمي واقي الشمس في روتينك الصباحي.</li></ul><div class="kbb-bl"></div></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تعتمد نومبوزين على نظام ترقيم بسيط يجعل اختيار منتجات العناية بالبشرة أسهل وفقاً لمشكلات البشرة وأهدافها المحددة. تضم مجموعتها من منتجات الجمال الكوري حلولاً موجّهة للمسام والترطيب والاحمرار والبقع الداكنة والحبوب وعلامات التقدّم في السن. ومع تركيبات تتمحور حول المكوّنات، تجعل نومبوزين العناية الكورية بالبشرة بسيطة وموجّهة وسهلة التخصيص.</div>'],
        'epii-new-skin-toner-snow-mushroom-pha' => ['إبي - تونر نيو سكين بفطر الثلج وPHA', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يقشّر مركّب PHA بنسبة 5% خلايا الجلد الميتة بلطف لتحسين مظهر الملمس الخشن وغير المتجانس.</li><li>يساعد مستخلص فطر الثلج على الاحتفاظ بالرطوبة ويمنح البشرة مظهراً ممتلئاً ومنتعشاً.</li><li>تساعد أشكال متعددة من حمض الهيالورونيك على تجديد الترطيب والحفاظ على مرونة البشرة.</li><li>يساعد البانثينول والجلسرين على تهدئة الجفاف ودعم حاجز الرطوبة في البشرة.</li><li>تُمتص التركيبة الخفيفة الخالية من العطور بسرعة، فتبدو البشرة ناعمة ومشرقة دون أي لمسة لزجة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد PHA (مركّب بنسبة 5%) على شكل الغلوكونولاكتون على التقشير اللطيف وتنعيم ملمس البشرة غير المتجانس.</li><li>يساعد فطر الثلج وحمض الهيالورونيك والبانثينول على تجديد الترطيب وتهدئة البشرة ودعم مظهرها الصحي.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف، ضعي كمية مناسبة على الوجه باستخدام راحتي يديكِ أو قطنة.</li><li>مرّري القطنة أو ربّتي بلطف على البشرة مع تجنّب منطقة العينين.</li><li>اتبعيه بالسيروم والمرطّب.</li><li>إذا كنتِ جديدة على التونرات المقشّرة، ابدئي باستخدامه 2–3 مرات أسبوعياً ثم زيدي عدد المرات بحسب تحمّل بشرتك.</li><li>ضعي واقي الشمس خلال النهار.</li></ul><div class="kbb-bl"></div></div><div><p>مناسب لجميع أنواع البشرة، وخاصةً البشرة الباهتة أو الجافة أو خشنة الملمس التي تحتاج إلى تقشير لطيف وترطيب. يُنصح أصحاب البشرة الحساسة بإدخال PHA تدريجياً.</p><p class="kbb-bl"></p></div><div><b>الحجم: </b><span>145 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من فكرة أن البشرة تتغيّر مع كل مرحلة من مراحل الحياة، تبتكر إبي منتجات عناية كورية بالبشرة مصمّمة لتتكيّف مع احتياجاتها المتغيّرة. تضم مجموعتها من منتجات الجمال الكوري تركيبات موجّهة بمكوّنات مثل الإكتوين والبانثينول وPHA والنياسيناميد والببتيدات للترطيب والعناية بالحاجز والإشراق وتحسين الملمس. وبنهج لطيف وهادف، تجعل إبي العناية العصرية بالبشرة أسهل في التخصيص لمختلف مشكلات البشرة والروتين اليومي.</div>'],
        'jumiso-niacinamide-20-serum' => ['جوميسو - سيروم النياسيناميد 20', '<div>خبر سار: لن تبقى البقع الداكنة وآثار الحبوب على وجهك بعد الآن. بتركيز 20% من النياسيناميد، صُمّم سيروم جوميسو نياسيناميد 20 للتقليل من هذه المشكلات. وتعزّز مكوّنات مفتّحة أخرى مثل حمض الترانيكساميك والجلوتاثيون معركتك من أجل بشرة صافية ومشرقة. كما يحتوي على مركّب السنتيلا الثلاثي وحمض الهيالورونيك لبشرة هادئة ومرطّبة. تركيبة خالية من العطور تُمتص بسرعة في البشرة لتمنحها لمسة نهائية مريحة دون أي لزوجة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على التقليل بشكل ملحوظ من مظهر البقع الداكنة وآثار الحبوب وتفاوت لون البشرة.</li><li>يدعم النياسيناميد بتركيز 20% بشرة تبدو أكثر إشراقاً ويساعد على تحسين مظهر الملمس غير المتجانس.</li><li>يوفّر حمض الترانيكساميك والجلوتاثيون عناية موجّهة إضافية للتصبّغات الظاهرة.</li><li>يساعد مركّب السنتيلا الثلاثي على تهدئة الاحمرار الظاهر ودعم راحة البشرة.</li><li>يساعد حمض الهيالورونيك ومشتقاته على الحفاظ على الترطيب لبشرة أنعم وأكثر نضارة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد النياسيناميد بتركيز 20% وحمض الترانيكساميك والجلوتاثيون على تحسين مظهر البقع الداكنة وتفاوت لون البشرة.</li><li>يساعد مركّب السنتيلا الثلاثي وحمض الهيالورونيك على تهدئة الاحمرار الظاهر وتجديد الترطيب.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، وزّعي بضع قطرات بالتساوي على الوجه.</li><li>ربّتي بلطف حتى يُمتص تماماً، ثم اتبعيه بالمرطّب.</li><li>استخدمي واقي الشمس خلال النهار للمساعدة على حماية البشرة من التصبّغات الناتجة عن الأشعة فوق البنفسجية.</li><li>إذا كنتِ جديدة على النياسيناميد عالي التركيز، ابدئي تدريجياً وأجري اختبار حساسية قبل الاستخدام المنتظم.</li></ul><div class="kbb-bl"></div></div><div>مناسب للبشرة التي تعاني من البقع الداكنة وآثار الحبوب وتفاوت لون البشرة والدهون الزائدة وخشونة الملمس. قد تحتاج البشرة الحساسة إلى إدخال هذه التركيبة عالية التركيز تدريجياً.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>40 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى جوميسو نهجاً عملياً يركّز على المكوّنات في العناية الكورية بالبشرة، فتبتكر تركيبات موجّهة لمشكلات البشرة اليومية. تضم مجموعتها من منتجات الجمال الكوري منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامينات والديكسبانثينول للترطيب والإشراق والتهدئة والعناية بالمسام والحاجز. وبتركيبات واضحة مبنية حول مكوّنات عناية معروفة، تجعل جوميسو الروتين اليومي سهل التخصيص والمواظبة.</div>'],
        'jumiso-waterfull-hyaluronic-acid-cleansing-foam' => ['جوميسو - رغوة منظفة بحمض الهيالورونيك ووترفول', '<div>رغوة التنظيف الناعمة والكريمية هذه غنية بالسيراميد ومركّب ثلاثي من حمض الهيالورونيك لمنح ترطيب عميق وتقوية حاجز البشرة. كما يزيل LHA في التركيبة الشوائب دون تجريد البشرة من رطوبتها.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>تزيل الشوائب اليومية والدهون الزائدة دون أن تترك البشرة جافة بشكل مفرط.</li><li>يساعد حمض الهيالورونيك الثلاثي على تجديد الرطوبة والحفاظ على ترطيب البشرة.</li><li>يدعم السيراميد NP حاجز الرطوبة الطبيعي في البشرة.</li><li>يقشّر LHA بلطف لتحسين مظهر الملمس الخشن وتراكمات المسام.</li><li>تترك الرغوة الكريمية الغنية البشرة ناعمة ومنتعشة ومريحة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد مركّب حمض الهيالورونيك الثلاثي على تجديد الرطوبة والحفاظ على ترطيب البشرة.</li><li>يدعم السيراميد NP وLHA حاجز الرطوبة مع تنعيم ملمس البشرة بلطف.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>ضعي كمية معتدلة على يدين مبللتين وافركيها حتى تتكوّن رغوة غنية.</li><li>دلّكي الوجه بلطف مع تجنّب منطقة العينين.</li><li>اشطفي جيداً بالماء الفاتر.</li><li>اتبعيها بالتونر والمرطّب.</li></ul><div class="kbb-bl"></div></div><div>مناسبة لجميع أنواع البشرة، وخاصةً البشرة العادية والجافة والمختلطة التي تحتاج إلى تنظيف مرطّب مع تقشير لطيف.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>150 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى جوميسو نهجاً عملياً يركّز على المكوّنات في العناية الكورية بالبشرة، فتبتكر تركيبات موجّهة لمشكلات البشرة اليومية. تضم مجموعتها من منتجات الجمال الكوري منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامينات والديكسبانثينول للترطيب والإشراق والتهدئة والعناية بالمسام والحاجز. وبتركيبات واضحة مبنية حول مكوّنات عناية معروفة، تجعل جوميسو الروتين اليومي سهل التخصيص والمواظبة.</div>'],
        'purito-seoul-oat-pdrn-gentle-refining-toner' => ['بيوريتو سيول - تونر التنعيم اللطيف بالشوفان وPDRN', '<div>يحتوي تونر بيوريتو سيول للتنعيم اللطيف بالشوفان وPDRN على 80% من ماء بذور الشوفان وPDRN نباتي المصدر لترطيب البشرة وتهدئة الانزعاج وتحسين مظهر الملمس غير المتجانس. تجمع تركيبته الحليبية الخفيفة بين البانثينول والبيتا جلوكان وزيت بذور الميدوفوم للمساعدة في الحفاظ على الرطوبة ودعم حاجز البشرة. صُمّم للعناية اليومية اللطيفة، ويترك البشرة ناعمة ومتوازنة ومنتعشة دون عطور صناعية.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>يساعد على تنعيم البشرة الخشنة وتحسين مظهر الملمس غير المتجانس.</li><li>يساعد ماء بذور الشوفان والجلسرين على تجديد الرطوبة.</li><li>يساعد البانثينول والبيتا جلوكان على تهدئة البشرة الجافة والحساسة.</li><li>يساعد زيت بذور الميدوفوم والبانثينول على الحفاظ على راحة البشرة.</li><li>يساعد على تحسين مظهر البشرة الباهتة والمتعبة.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>ماء بذور الشوفان 80% وPDRN الشوفان: يساعدان على ترطيب البشرة وتهدئتها وتحسين مظهر ملمسها.</li><li>البانثينول والبيتا جلوكان: يساعدان على الحفاظ على الرطوبة ودعم حاجز البشرة.</li></ul></div></div><div class="kbb-bl"></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>بعد التنظيف، ضعي كمية معتدلة على راحتي يديكِ أو على قطنة.</li><li>مرّريها بلطف على الوجه ثم ربّتي حتى يمتصّها الجلد.</li><li>لترطيب إضافي، اغمري أقراص القطن بالتونر وضعيها على المناطق الجافة لمدة 5–10 دقائق.</li><li>استخدميه صباحاً ومساءً.</li><li>مناسب لجميع أنواع البشرة، بما في</li></ul><div class="kbb-bl"></div><div>مناسب لجميع أنواع البشرة، بما فيها البشرة الحساسة والجافة والمعرّضة لحب الشباب التي تعاني من الجفاف وخشونة الملمس والبهتان.</div><div class="kbb-bl"></div></div></div><div><b>الحجم: </b>200 مل</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى بيوريتو سيول نهجاً يضع البشرة أولاً ويؤمن بأن القليل يكفي في العناية الكورية بالبشرة، فتركّز على ما تحتاجه بشرتكِ فعلاً وتستغني عمّا لا داعي له. وانطلاقاً من المكوّنات المهدّئة والعناية بحاجز البشرة، تبتكر العلامة تركيبات لطيفة وهادفة تساعد البشرة المجهدة على استعادة مظهر هادئ ومتوازن وصحي.</div>'],
        'mixsoon-bean-cleansing-oil-jumbo' => ['ميكسون - زيت التنظيف بفول الصويا جامبو', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يذيب المكياج وواقي الشمس المقاوم للماء والشوائب اليومية بفعالية لتنظيف أوّلي شامل.</li><li>يساعد زيت فول الصويا وزيت الجوجوبا على إزالة الدهون الزائدة مع الحفاظ على الرطوبة الطبيعية للبشرة.</li><li>تساعد خلاصات فول الصويا المخمّر والشعير والرمان والكمثرى على تغذية البشرة ومنحها مظهراً منتعشاً.</li><li>تتحوّل التركيبة الخفيفة إلى مستحلب عند ملامسة الماء وتُشطف دون أن تترك إحساساً ثقيلاً أو دهنياً.</li><li>يساعد على إبقاء البشرة ناعمة ومرتاحة ورطبة بعد التنظيف.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>زيت فول الصويا وزيت بذور الجوجوبا: يساعدان على إذابة المكياج وواقي الشمس والدهون الزائدة مع الحفاظ على نعومة البشرة.</li><li>خلاصتا فول الصويا المخمّر والشعير: تساعدان على تغذية البشرة والحفاظ على إحساس رطب ومريح. </li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>ضعي 2–3 ضخّات على يدين جافتين ودلّكي بلطف على وجه جاف.</li><li>أضيفي قليلاً من الماء واستمري في التدليك حتى يتحوّل الزيت إلى قوام حليبي.</li><li>اشطفي جيداً بالماء الفاتر.</li><li>أكملي بغسول مائي للتنظيف المزدوج. </li></ul></div><div class="kbb-bl"></div><div>مناسب لجميع أنواع البشرة، وخاصة لمن تضع المكياج أو واقي الشمس وترغب في إزالة الزيوت الزائدة والشوائب دون جفاف مفرط.</div><div class="kbb-bl"></div><div><b>الحجم: </b>195 مل</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تجسّد ميكسون روح البساطة في العناية الكورية بالبشرة، فتركّز على مكوّنات نقية مختارة بعناية وتركيبات مبسّطة تجعل البشرة محور الاهتمام. وتشتهر بخلاصاتها المميّزة من السنتيلا وفول الصويا والجالاكتوميسيس، وتبتكر منتجات خفيفة ومهدّئة مصمّمة لترطيب البشرة وتقوية حاجزها وإبراز إشراقتها الصحية الطبيعية.</div>'],
        'numbuzin-no-5-glutathione-txa-advanced-dark-spot-ampoule-concentrate' => ['نومبوزين - أمبول مركّز متقدّم للبقع الداكنة بالجلوتاثيون وTXA رقم 5', null, '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد الجلوتاثيون وحمض الترانيكساميك على تحسين مظهر البقع الداكنة والتصبّغات وآثار حب الشباب لبشرة أكثر توحّداً.</li><li>يساعد النياسيناميد على تفتيح البشرة الباهتة وتحسين مظهر لون البشرة غير المتجانس.</li><li>يساعد ماء شجرة الفيتامين وفيتامين سي على منح البشرة مظهراً مشرقاً ومنتعشاً.</li><li>يساعد البانثينول والجلسرين على الحفاظ على الرطوبة وإبقاء البشرة ناعمة ومرتاحة.</li><li>تحفظ العبوة بتقنية الضغط والمزج مسحوق الجلوتاثيون منفصلاً حتى وقت الاستخدام لعلاج تفتيح مُفعَّل وطازج.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد الجلوتاثيون وحمض الترانيكساميك على استهداف مظهر البقع الداكنة والتصبّغات وتفاوت لون البشرة.</li><li>يساعد النياسيناميد وفيتامين سي والبانثينول على تفتيح البشرة مع دعم الترطيب وراحة البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>قبل الاستخدام الأول، اضغطي على الغطاء الأصفر لإطلاق مسحوق الجلوتاثيون داخل الأمبول.</li><li>رجّي جيداً حتى يمتزج المسحوق تماماً، ثم استبدلي الغطاء بالقطّارة.</li><li>ضعي كمية صغيرة على مناطق البقع الداكنة أو اللون غير المتجانس وربّتي بلطف حتى يمتصّها الجلد.</li><li>أكملي بالمرطّب وضعي واقي الشمس خلال النهار.</li></ul><div class="kbb-bl"></div></div><div>مناسب لجميع أنواع البشرة التي تعاني من البقع الداكنة وآثار حب الشباب والبهتان وتفاوت لون البشرة. أجري اختبار حساسية قبل الاستخدام، خاصة إذا كانت بشرتكِ حساسة.<b></b></div><div class="kbb-bl"></div><div><b>الحجم: </b><span>10.7 غ</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تعتمد نومبوزين على نظام ترقيم بسيط يسهّل اختيار منتجات العناية بالبشرة بحسب مشكلات البشرة وأهدافها. تضم مجموعتها الكورية حلولاً موجّهة للمسام والترطيب والاحمرار والبقع الداكنة والحبوب وعلامات التقدّم في السن. وبتركيبات تتمحور حول المكوّنات، تجعل نومبوزين العناية الكورية بالبشرة بسيطة وموجّهة وسهلة التخصيص.</div>'],
        'skin1004-madagascar-centella-tone-brightening-cleansing-gel-foam' => ['سكين 1004 - رغوة جل منظفة لتفتيح البشرة بسنتيلا مدغشقر', null, '<div><span><b>الفوائد الرئيسية:</b></span></div><div><ul><li>يزيل الشوائب اليومية والدهون الزائدة بلطف مع المساعدة في الحفاظ على توازن الرطوبة الطبيعي للبشرة.</li><li>تساعد السنتيلا الآسيوية والماديكاسوسايد على تهدئة البشرة ودعم مظهرها الصحي.</li><li>يساعد النياسيناميد على تحسين مظهر تفاوت لون البشرة والبهتان لمظهر أكثر إشراقاً.</li><li>يساعد أحد مشتقات فيتامين سي على تعزيز الإشراقة وتحسين مظهر اللون غير المتجانس.</li><li>تساعد مكوّنات التقشير المستخلصة من الفواكه على إزالة خلايا الجلد الميتة، فتصبح البشرة أنعم وأكثر انتعاشاً.</li></ul></div><div><span>صُنع في كوريا </span></div><div class="kbb-bl"></div><div><span><b>المكوّنات الأساسية: </b></span></div><div><ul><li><span>تساعد خلاصة السنتيلا الآسيوية من مدغشقر والماديكاسوسايد على تهدئة البشرة ودعم راحتها.</span></li><li><span>يساعد النياسيناميد و3-O-Ethyl Ascorbic Acid على تحسين مظهر البهتان وتفاوت لون البشرة.</span></li></ul><div class="kbb-bl"></div></div><div><span><b>طريقة الاستخدام: </b></span></div><div><ul><li><span>بلّلي وجهكِ بالماء الفاتر.</span></li><li><span>ضعي كمية مناسبة على راحتي يديكِ المبلّلتين وافركيهما معاً لتكوين رغوة.</span></li><li><span>دلّكي الوجه بلطف مع تجنّب منطقة العينين.</span></li><li><span>اشطفي جيداً بالماء الفاتر وأكملي روتين العناية ببشرتكِ.</span></li></ul></div><div class="kbb-bl"></div><div><span><b>الحجم: </b>125 مل</span></div><div class="kbb-bl"></div><div><span><b>عن العلامة التجارية: </b>ترتكز سكين 1004 على نقاء السنتيلا الآسيوية من مدغشقر، وتبتكر منتجات لطيفة للعناية بالبشرة تركّز على تهدئتها واستعادة حيويتها. تضم مجموعتها الكورية تركيبات للترطيب والتفتيح والعناية بالحاجز والتهدئة، مصنوعة من مكوّنات مختارة بعناية. وتجمع سكين 1004 بين التركيبات البسيطة والمكوّنات المستوحاة من الطبيعة لدعم بشرة مرتاحة ومتوازنة وصحية المظهر.</span></div>'],
        'epii-hpt6-ultra-drop-10' => ['إبي - قطرات HPT6 ألترا 10%', '<div>هل تبحثين عن سيروم لمكافحة علامات التقدّم في السن لا يكتفي بالعمل على السطح؟ قطرات إبي HPT6 ألترا 10% سيروم لشدّ البشرة يحتوي على المكوّن المميّز للعلامة HPT6 (المكوّن من هيدروكسي بروبيل تتراهيدروبيرانتريول الذي يدعم تماسك البشرة) وMatrixyl Synthe’6 (ببتيد يحفّز البشرة على دعم إنتاج الكولاجين). تستهدف هذه التركيبة القوية فقدان المرونة، مع استعادة ترطيب البشرة وتقوية حاجزها.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد HPT (10%) على تحسين مظهر تماسك البشرة ومرونتها لبشرة أنعم مظهراً.</li><li>يساعد Matrixyl Synthé’6 (2%) على استهداف الخطوط الدقيقة الظاهرة ودعم مظهر أكثر تماسكاً ونضارة.</li><li>يساعد البانثينول والجلسرين على تجديد الرطوبة ودعم الحاجز الطبيعي للبشرة.</li><li>يساعد الإكتوين والألانتوين على تنعيم البشرة والحفاظ على راحتها.</li><li>التركيبة الخفيفة غير الدهنية تمتصّ بسرعة ويسهل وضعها مع منتجات العناية الأخرى والمكياج.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد HPT (10%) وMatrixyl Synthé’6 (2%) على تحسين مظهر الخطوط الدقيقة ودعم تماسك البشرة.</li><li>يساعد البانثينول والإكتوين والجلسرين على الحفاظ على الترطيب ودعم حاجز البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي كمية مناسبة على الوجه والرقبة.</li><li>وزّعيه بلطف وربّتي حتى يمتصّه الجلد تماماً.</li><li>أكملي بمرطّب للمساعدة في الاحتفاظ بالترطيب.</li><li>استخدميه صباحاً ومساءً، وضعي واقي الشمس كخطوة أخيرة في روتينكِ الصباحي.</li></ul><div class="kbb-bl"></div></div><div>مناسب لجميع أنواع البشرة، وخاصة البشرة التي تعاني من الخطوط الدقيقة وضعف المرونة وفقدان التماسك.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من فكرة أن البشرة تتغيّر مع كل مرحلة من مراحل الحياة، تبتكر إبي منتجات كورية للعناية بالبشرة مصمّمة لتتكيّف مع احتياجاتها المتغيّرة. تضم مجموعتها الكورية تركيبات موجّهة بمكوّنات مثل الإكتوين والبانثينول وPHA والنياسيناميد والببتيدات للترطيب والعناية بالحاجز والإشراقة والملمس. وبنهج لطيف وهادف، تجعل إبي العناية الحديثة بالبشرة أسهل في التخصيص لمختلف مشكلات البشرة والروتين اليومي.</div>'],
        'jumiso-niacinamide-10-serum' => ['جوميسو - سيروم النياسيناميد 10', '<div>هذا السيروم المعزّز للإشراقة غنيّ بالنياسيناميد وحمض السكسينيك وحمض الترانيكساميك لتوحيد لون البشرة وتنعيم ملمسها وتقليل مظهر المسام الواسعة. وتمنح المكوّنات الإضافية من خلاصة الرجلة وحمض الهيالورونيك والسكوالان فوائد مهدّئة ومرطّبة. التركيبة الخالية من العطور مناسبة للبشرة الحساسة والمعرّضة لحب الشباب.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد النياسيناميد (10%) على تفتيح البشرة الباهتة وتحسين مظهر البقع الداكنة وتفاوت لون البشرة.</li><li>يساعد حمض الترانيكساميك والجلوتاثيون على استهداف مظهر التصبّغات وآثار حب الشباب لبشرة أكثر توحّداً.</li><li>يساعد حمض السكسينيك وZinc PCA على التحكّم في الدهون الزائدة وتقليل مظهر المسام الواسعة.</li><li>يساعد حمض الهيالورونيك والسكوالان على تجديد الرطوبة، فتصبح البشرة ناعمة ومرنة.</li><li>يساعد مركّب السنتيلا الثلاثي على تهدئة الاحمرار الظاهر ودعم حاجز البشرة دون ملمس ثقيل أو لزج.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد النياسيناميد (10%) وحمض الترانيكساميك والجلوتاثيون على تحسين مظهر البقع الداكنة وتفاوت لون البشرة.</li><li>تساعد مكوّنات حمض السكسينيك وZinc PCA وحمض الهيالورونيك والسنتيلا على التحكّم في الدهون الزائدة والحفاظ على الترطيب وتهدئة البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي بضع قطرات على الوجه.</li><li>وزّعيه بلطف وربّتي حتى يمتصّه الجلد تماماً.</li><li>أكملي بمرطّب للحفاظ على الترطيب.</li><li>استخدميه صباحاً ومساءً، مع وضع واقي الشمس خلال النهار.</li></ul></div><div class="kbb-bl"></div><div><p>مناسب للبشرة الدهنية والمختلطة والمعرّضة لحب الشباب التي تعاني من البقع الداكنة وتفاوت اللون والدهون الزائدة والمسام الظاهرة.</p><p class="kbb-bl"></p></div><div><b>الحجم: </b><span>40 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى جوميسو نهجاً عملياً يتمحور حول المكوّنات في العناية الكورية بالبشرة، فتبتكر تركيبات موجّهة لمشكلات البشرة اليومية. تضم مجموعتها الكورية منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامين وD-Panthenol للترطيب والتفتيح والتهدئة والعناية بالمسام والحاجز. وبتركيبات واضحة مبنية على مكوّنات معروفة للعناية بالبشرة، تجعل جوميسو الروتين اليومي سهل التخصيص والمتابعة.</div>'],
        'jumiso-blackhead-melting-softener-special-set' => ['جوميسو - مجموعة خاصة لمليّن إذابة الرؤوس السوداء', '<div>تخلّصي من الرؤوس السوداء العنيدة مع هذا المليّن اللطيف والفعّال. تركيبته غنية بحمض السكسينيك وPHA وماء السرو لفوائد مضادة للميكروبات ومهدّئة ومقشّرة، لمسام منظّفة تماماً. للاستخدام، اغمري أقراص القطن المرفقة وضعيها على المناطق المطلوبة لمدة 10 إلى 15 دقيقة لتليين الدهون. استخدمي أدوات العناية بالمسام لإزالة الدهون الليّنة بلطف، ثم اشطفي البشرة بالماء الفاتر وجفّفيها بالتربيت. تتضمّن المجموعة مليّن إذابة الرؤوس السوداء واحداً ومجموعة من 40 قرصاً قطنياً.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تليين الرؤوس السوداء وتفكيك الدهون الزائدة من المسام المسدودة.</li><li>يدعم حمض السكسينيك العناية الموجّهة للبشرة الدهنية المعرّضة للحبوب.</li><li>يقشّر PHA بلطف لتحسين مظهر الملمس غير المتجانس.</li><li>يساعد ماء السرو على تهدئة البشرة، بينما تدعم المكوّنات المرطّبة ترطيبها.</li><li>يتضمّن أقراصاً قطنية لاستخدام مريح وموجّه.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية:</b></div><div><ul><li>يساعد حمض السكسينيك وPHA على تليين الدهون الزائدة وتنعيم ملمس البشرة غير المتجانس.</li><li>يساعد ماء السرو والبانثينول على تهدئة البشرة والحفاظ على رطوبتها.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>ضعي المليّن بسخاء على قرص قطني وضعيه على المناطق النظيفة والجافة المعرّضة للرؤوس السوداء.</li><li>اتركيه لمدة 10–15 دقيقة، ثم أزيلي الدهون الليّنة بلطف باستخدام أداة مناسبة للعناية بالمسام أو عود قطني.</li><li>اشطفي جيداً بالماء الفاتر وأكملي روتين العناية ببشرتكِ.</li><li>استخدميه 1–2 مرة أسبوعياً للبشرة الدهنية أو مرة واحدة أسبوعياً للبشرة الحساسة. تجنّبي العصر بقوة.</li></ul><div class="kbb-bl"></div></div><div>مناسب للبشرة الدهنية والمختلطة والمعرّضة لانسداد المسام التي تعاني من الرؤوس السوداء والدهون الزائدة والمسام الظاهرة.</div><div class="kbb-bl"></div><div><b>الحجم: </b>150 مل مليّن إذابة الرؤوس السوداء + 40 قرصاً قطنياً</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تتبنّى جوميسو نهجاً عملياً يتمحور حول المكوّنات في العناية الكورية بالبشرة، فتبتكر تركيبات موجّهة لمشكلات البشرة اليومية. تضم مجموعتها الكورية منتجات بمخاط الحلزون وحمض الهيالورونيك والنياسيناميد والفيتامين وD-Panthenol للترطيب والتفتيح والتهدئة والعناية بالمسام والحاجز. وبتركيبات واضحة مبنية على مكوّنات معروفة للعناية بالبشرة، تجعل جوميسو الروتين اليومي سهل التخصيص والمتابعة.</div>'],
        'medicube-deep-vita-c-capsule-serum' => ['ميديكوب - سيروم الكبسولات ديب فيتا سي', '<div>امنحي بشرتكِ دفعة الإشراقة التي تحتاجها مع سيروم الكبسولات ديب فيتا سي من ميديكوب! بفضل فيتامين سي عالي النقاء والنياسيناميد وماء نبق البحر، يعمل هذا الثلاثي من مكوّنات التفتيح معاً لتوحيد لون البشرة غير المتجانس وإنعاش البشرة الباهتة. يمتصّ الجلد فيتامين سي المغلّف بالليبوسومات بسرعة لنتيجة صافية ومتألّقة.</div><div><br></div><div><div><b>الأفضل مع:</b> كريم الكبسولات ديب فيتا سي الشهير من ميديكوب لقوة مضاعفة في مكافحة العيوب مع حبس الترطيب.</div></div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تفتيح البشرة الباهتة وتعزيز إشراقتها الطبيعية.</li><li>يساعد النياسيناميد بتركيز 5% على تحسين مظهر تفاوت لون البشرة والبقع الداكنة.</li><li>يساعد فيتامين سي المغلّف على منح البشرة مظهراً أكثر صفاءً وتألّقاً.</li><li>ينعش ماء نبق البحر البشرة ويدعم توهّجها الصحي.</li><li>يساعد حمض الهيالورونيك وفيتامين E على الحفاظ على الرطوبة ويتركان البشرة ناعمة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد فيتامين سي المغلّف والنياسيناميد بتركيز 5% على تفتيح البشرة الباهتة وتحسين مظهر اللون غير المتجانس.</li><li>يساعد ماء نبق البحر بنسبة 77% وحمض الهيالورونيك والجلوتاثيون على إنعاش البشرة وترطيبها ومنحها مظهراً مشرقاً.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>بعد التنظيف واستخدام التونر، ضعي كمية معتدلة على الوجه.</li><li>دلّكي بلطف حتى تذوب كبسولات فيتامين سي ويمتصّ الجلد السيروم.</li><li>أكملي بالمرطّب.</li><li>استخدمي واقي الشمس خلال النهار لحماية البشرة من التصبّغات الناتجة عن الأشعة فوق البنفسجية.</li></ul><div class="kbb-bl"></div></div><div><p>مناسب للبشرة الباهتة غير المتجانسة التي تعاني من البقع الداكنة وآثار حب الشباب وقلة الإشراقة والجفاف</p><p class="kbb-bl"></p></div><div><b>الحجم: </b><span>30 مل</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>انطلاقاً من تقنيات التجميل الكورية، تجمع ميديكوب بين تركيبات العناية بالبشرة وحلول متقدّمة مصمّمة لمشكلات البشرة اليومية. تضم مجموعتها الكورية منتجات للعناية بالمسام والترطيب والإشراقة والمرونة والحاجز، إلى جانب أجهزة التجميل المبتكرة AGE-R. وبتركيبات قائمة على الأبحاث وتقنيات تجميل منزلية، تقدّم ميديكوب نهجاً أكثر استهدافاً للعناية الحديثة بالبشرة.</div>'],
        'sebum-sweeper-pore-cleansing-silicone-brush' => [null, '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>تساعد على إزالة الدهون الزائدة والشوائب السطحية.</li><li>تدعم تنظيف المناطق المعرّضة للرؤوس السوداء.</li><li>تصل إلى المناطق الصعبة حول الأنف والذقن.</li><li>تصميم سيليكون قابل لإعادة الاستخدام وسهل التنظيف.</li><li>متوافقة مع غسولات الوجه وبلسم التنظيف.</li></ul></div></div><div>صُنع في كوريا </div><div><br></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>سيليكون مرن: يساعد على تدليك البشرة وإزالة الشوائب السطحية أثناء التنظيف.</li><li>تصميم بثلاثة رؤوس: يجمع بين أشكال رؤوس مختلفة لتنظيف موجّه حول المسام والمناطق المسدودة.</li></ul><div><br></div></div></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>ضعي غسول الوجه المعتاد على بشرة رطبة.</li><li>دلّكي الأنف والذقن والمناطق الأخرى المعنية بلطف باستخدام شعيرات السيليكون المستديرة.</li><li>استخدمي ضغطاً خفيفاً وتجنّبي الفرك العنيف.</li><li>اشطفي وجهكِ والفرشاة جيداً بعد الاستخدام.</li><li>في حال حدوث تهيّج أو احمرار، قلّلي الاستخدام إلى 2–3 مرات أسبوعياً.</li></ul><div><br></div></div></div><div>مناسبة للبشرة الدهنية أو المختلطة التي تعاني من الدهون الزائدة والرؤوس السوداء والرؤوس البيضاء والمسام المسدودة.</div><div><br></div><div><b>عن العلامة التجارية: </b>تستلهم أبريل سكين من الطبيعة لتبتكر منتجات منعشة للعناية بالبشرة والتجميل تتمحور حول المكوّنات للروتين اليومي. تشتهر مجموعتها الكورية بتركيبات الكاروتين والآذريون والشيح والسنتيلا التي تستهدف الترطيب والتهدئة والعيوب وملمس البشرة. ومن بلسم التنظيف والسيرومات إلى الأقنعة والمكياج، تقدّم أبريل سكين جمالاً كورياً متعدّد الاستخدامات ضمن عناية يومية بسيطة.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><div><ul><li>تساعد على إزالة الدهون الزائدة والشوائب السطحية.</li><li>تدعم تنظيف المناطق المعرّضة للرؤوس السوداء.</li><li>تصل إلى المناطق الصعبة حول الأنف والذقن.</li><li>تصميم سيليكون قابل لإعادة الاستخدام وسهل التنظيف.</li><li>متوافقة مع غسولات الوجه وبلسم التنظيف.</li></ul></div></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><div><ul><li>سيليكون مرن: يساعد على تدليك البشرة وإزالة الشوائب السطحية أثناء التنظيف.</li><li>تصميم بثلاثة رؤوس: يجمع بين أشكال رؤوس مختلفة لتنظيف موجّه حول المسام والمناطق المسدودة.</li></ul><div class="kbb-bl"></div></div></div><div><b>طريقة الاستخدام: </b></div><div><div><ul><li>ضعي غسول الوجه المعتاد على بشرة رطبة.</li><li>دلّكي الأنف والذقن والمناطق الأخرى المعنية بلطف باستخدام شعيرات السيليكون المستديرة.</li><li>استخدمي ضغطاً خفيفاً وتجنّبي الفرك العنيف.</li><li>اشطفي وجهكِ والفرشاة جيداً بعد الاستخدام.</li><li>في حال حدوث تهيّج أو احمرار، قلّلي الاستخدام إلى 2–3 مرات أسبوعياً.</li></ul><div class="kbb-bl"></div></div></div><div>مناسبة للبشرة الدهنية أو المختلطة التي تعاني من الدهون الزائدة والرؤوس السوداء والرؤوس البيضاء والمسام المسدودة.</div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تستلهم أبريل سكين من الطبيعة لتبتكر منتجات منعشة للعناية بالبشرة والتجميل تتمحور حول المكوّنات للروتين اليومي. تشتهر مجموعتها الكورية بتركيبات الكاروتين والآذريون والشيح والسنتيلا التي تستهدف الترطيب والتهدئة والعيوب وملمس البشرة. ومن بلسم التنظيف والسيرومات إلى الأقنعة والمكياج، تقدّم أبريل سكين جمالاً كورياً متعدّد الاستخدامات ضمن عناية يومية بسيطة.</div>'],
        'medipeel-gold-age-tox-h8-cream-2' => ['ميدي بيل - كريم جولد إيج توكس H8', '<div>يحتوي هذا الكريم المضاد لعلامات التقدّم في السن على كبسولات غنية بالمغذّيات وكولاجين نباتي لاستعادة مرونة البشرة ومنحها مظهرًا ممتلئًا وشبابيًا. التركيبة الجلّية غنية بـ19 نوعًا من الأحماض الأمينية ومركّب بروتين الحرير الذهبي لتغذية البشرة وتعزيز إشراقها. كما تحتوي على الأدينوسين لتقليل مظهر التجاعيد. يأتي مع ملعقة صغيرة لمزج الكبسولات والجل معًا قبل وضعه على الوجه.</div>', '<div><b>الفوائد الرئيسية:</b></div><div><ul><li>يساعد على تحسين مظهر الخطوط الدقيقة وفقدان الشدّ.</li><li>يدعم النياسيناميد بشرة أكثر إشراقًا وتوحّدًا.</li><li>تساعد الببتيدات والكولاجين على منح البشرة مظهرًا أنعم وأكثر امتلاءً.</li><li>تساعد خمسة أنواع من السيراميدات على الحفاظ على الرطوبة ودعم حاجز البشرة.</li><li>يغذّي الجلسرين والبانثينول والسكوالان البشرة ويساعدون على منع فقدان الرطوبة.</li></ul></div><div>صُنع في كوريا </div><div class="kbb-bl"></div><div><b>المكوّنات الأساسية: </b></div><div><ul><li>يساعد النياسيناميد والأدينوسين والببتيدات على تحسين مظهر عدم توحّد اللون والخطوط الدقيقة.</li><li>تساعد خمسة أنواع من السيراميدات والبانثينول والسكوالان على تجديد الرطوبة ودعم حاجز البشرة.</li></ul><div class="kbb-bl"></div></div><div><b>طريقة الاستخدام: </b></div><div><ul><li>باستخدام الملعقة المرفقة، اغرفي الكبسولات مع الجل المرطّب.</li><li>امزجيهما على ظهر يدك حتى يمتزجا بالتساوي.</li><li>ضعيه على الوجه ودلّكي برفق حتى يُمتصّ.</li><li>استخدميه كخطوة أخيرة في روتين العناية ببشرتك.</li></ul><div class="kbb-bl"></div></div><div>الأنسب للبشرة العادية والجافة والناضجة التي تعاني من الخطوط الدقيقة وفقدان الشدّ وعدم توحّد اللون والجفاف.</div><div class="kbb-bl"></div><div><b>الحجم: </b><span>50 غ</span></div><div class="kbb-bl"></div><div><b>عن العلامة التجارية: </b>تجمع ميدي بيل بين الخبرة التجميلية الاحترافية وأبحاث الأمراض الجلدية لتبتكر منتجات عناية مستهدفة للاستخدام اليومي. تتنوّع مجموعاتها بين علاجات التقشير المتقدّمة والعناية المشدّة الغنية بالببتيدات وتركيبات الترطيب وتجديد البشرة، وكلّ منها مصمّم لمشكلات بشرة محدّدة. ومن خلال الجمع بين الخبرة التجميلية والتركيبات المُختبرة سريريًا، تجعل ميدي بيل العناية المستوحاة من العيادات الاحترافية جزءًا من الروتين اليومي.</div>'],
    ];

    /** brand name as stored => Arabic. */
    private const BRANDS = ['EUNYUL' => 'يونيول', 'MEDI-PEEL' => 'ميدي بيل', 'MEDIPEEL' => 'ميدي بيل'];

    private const FIELDS = ['name', 'short_description', 'description'];

    public function up(): void
    {
        if (! Schema::hasTable('translations') || ! Schema::hasTable('products')) {
            return;
        }

        $written = 0;
        $skipped = 0;
        $products = DB::table('products')->whereIn('slug', array_keys(self::PRODUCTS))->get(['id', 'slug', 'name', 'short_description', 'description']);

        foreach ($products as $p) {
            foreach (self::PRODUCTS[$p->slug] as $i => $value) {
                if ($value === null || trim((string) $value) === '') {
                    continue;
                }

                $field = self::FIELDS[$i];
                $this->put('products', (int) $p->id, $field, $value, (string) ($p->{$field} ?? '')) ? $written++ : $skipped++;
            }
        }

        if (Schema::hasTable('brands')) {
            foreach (DB::table('brands')->whereIn('name', array_keys(self::BRANDS))->get(['id', 'name']) as $b) {
                $this->put('brands', (int) $b->id, 'name', self::BRANDS[$b->name], (string) $b->name) ? $written++ : $skipped++;
            }
        }

        try {
            \App\Services\Translation\TranslationStore::flush();
        } catch (\Throwable) {
            // The caches expire on their own.
        }

        if (app()->runningInConsole() && ! app()->runningUnitTests()) {
            echo "Arabic product text: {$written} field(s) written, {$skipped} already had Arabic and were left as they are.\n";
        }
    }

    /** Takes back only rows still holding exactly what this wrote. */
    public function down(): void
    {
        if (! Schema::hasTable('translations')) {
            return;
        }

        $ids = DB::table('products')->whereIn('slug', array_keys(self::PRODUCTS))->pluck('id', 'slug');

        foreach (self::PRODUCTS as $slug => $values) {
            foreach ($values as $i => $value) {
                if ($value !== null && isset($ids[$slug])) {
                    DB::table('translations')->where(['locale' => 'ar', 'group' => 'products', 'item_id' => $ids[$slug], 'field' => self::FIELDS[$i], 'value' => $value])->delete();
                }
            }
        }
    }

    /** True when written; false when published Arabic was already there. */
    private function put(string $group, int $id, string $field, string $value, string $english): bool
    {
        $key = ['locale' => 'ar', 'group' => $group, 'item_id' => $id, 'field' => $field];
        $row = DB::table('translations')->where($key)->first(['id', 'status', 'value']);

        if ($row !== null && $row->status === 'published' && trim((string) $row->value) !== '') {
            return false;
        }

        $data = ['value' => $value, 'status' => 'published', 'source' => 'manual', 'source_hash' => sha1($english),
            'reviewed_at' => now(), 'updated_at' => now()];

        $row === null
            ? DB::table('translations')->insert($key + $data + ['created_at' => now()])
            : DB::table('translations')->where('id', $row->id)->update($data);

        return true;
    }
};
